option.value:
/* ========================================
   DASHBOARD PRINCIPAL - Fondo Personalizable
   ======================================== */

.dashboardContainer {
  position: relative;
  min-height: 100vh;
  width: 100%;
  overflow-x: hidden;
}

/* ========================================
   IMAGEN DE FONDO PERSONALIZABLE
   ======================================== */

.backgroundImage {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 0;

  /*
    ⚙️ LA IMAGEN SE CONFIGURA EN:
    /src/config/backgroundConfig.js

     CAMBIA LA URL, BLUR Y OPACIDAD ALLÍ

    Formatos recomendados: JPG, WebP, PNG
    Tamaño recomendado: 1920x1080px o superior
  */

  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  background-attachment: fixed;

  /* El blur se aplica dinámicamente desde backgroundConfig.js */
}

/* Overlay oscuro para mejor legibilidad */
.overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  /* El gradiente se aplica dinámicamente desde backgroundConfig.js */
  z-index: 1;
  pointer-events: none;
}

/* ========================================
   CONTENIDO PRINCIPAL
   ======================================== */

.content {
  position: relative;
  z-index: 2;
  padding: 2rem;
  max-width: 1400px;
  margin: 0 auto;
  animation: fadeIn 0.6s ease-out;
}

/* ========================================
   TARJETA DE BIENVENIDA (Glassmorphism)
   ======================================== */

.welcomeCard {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(20px);
  border-radius: 24px;
  padding: 3rem;
  margin-bottom: 2rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  animation: slideDown 0.6s ease-out;
}

.welcomeHeader {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 1.5rem;
  gap: 2rem;
}

.welcomeTitle {
  font-size: 2.5rem;
  font-weight: 700;
  color: white;
  margin: 0 0 0.5rem 0;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
}

.welcomeSubtitle {
  font-size: 1.2rem;
  color: rgba(255, 255, 255, 0.9);
  margin: 0;
  font-weight: 400;
}

.timeDisplay {
  text-align: right;
  color: white;
}

.time {
  font-size: 2.5rem;
  font-weight: 700;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
  font-variant-numeric: tabular-nums;
}

.date {
  font-size: 1rem;
  opacity: 0.9;
  text-transform: capitalize;
  margin-top: 0.5rem;
}

.welcomeMessage {
  color: rgba(255, 255, 255, 0.95);
  font-size: 1.1rem;
  line-height: 1.6;
  margin: 0;
}

/* ========================================
   ESTADÍSTICAS RÁPIDAS
   ======================================== */

.statsGrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
  margin-bottom: 3rem;
  animation: fadeInUp 0.6s ease-out 0.2s backwards;
}

.statCard {
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(10px);
  border-radius: 16px;
  padding: 2rem;
  display: flex;
  align-items: center;
  gap: 1.5rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
  transition: all 0.3s ease;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
  position: relative;
  overflow: hidden;
}

.statCard::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: var(--stat-color, #52b788);
  transform: scaleY(0);
  transition: transform 0.3s ease;
}

.statCard:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.3);
  background: rgba(255, 255, 255, 0.2);
}

.statCard:hover::before {
  transform: scaleY(1);
}

.statIcon {
  font-size: 3rem;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.2));
}

.statInfo {
  flex: 1;
}

.statValue {
  font-size: 2rem;
  font-weight: 700;
  color: white;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);
}

.statLabel {
  font-size: 0.95rem;
  color: rgba(255, 255, 255, 0.9);
  margin-top: 0.25rem;
}

/* ========================================
   FUNCIONALIDADES DISPONIBLES
   ======================================== */

.featuresSection {
  margin-bottom: 3rem;
  animation: fadeInUp 0.6s ease-out 0.4s backwards;
}

.sectionTitle {
  font-size: 2rem;
  font-weight: 700;
  color: white;
  margin-bottom: 2rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
}

.sectionTitle span {
  font-size: 2.5rem;
}

.featuresGrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.featureCard {
  background: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(15px);
  border-radius: 20px;
  padding: 2.5rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.featureCard::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 5px;
  background: var(--feature-color, #52b788);
  transform: scaleX(0);
  transition: transform 0.4s ease;
}

.featureCard:hover {
  transform: translateY(-10px) scale(1.02);
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4);
  background: rgba(255, 255, 255, 0.18);
}

.featureCard:hover::before {
  transform: scaleX(1);
}

.featureIcon {
  font-size: 4rem;
  margin-bottom: 1.5rem;
  filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.3));
  animation: float 3s ease-in-out infinite;
}

.featureTitle {
  font-size: 1.5rem;
  font-weight: 700;
  color: white;
  margin: 0 0 1rem 0;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);
}

.featureDescription {
  color: rgba(255, 255, 255, 0.9);
  line-height: 1.6;
  margin: 0 0 2rem 0;
  flex: 1;
}

.featureButton {
  background: var(--feature-color, #52b788);
  color: white;
  border: none;
  padding: 0.875rem 2rem;
  border-radius: 12px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
  width: 100%;
}

.featureButton:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
  filter: brightness(1.1);
}

/* ========================================
   TARJETAS DE INFORMACIÓN
   ======================================== */

.infoCards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1.5rem;
  margin-bottom: 3rem;
  animation: fadeInUp 0.6s ease-out 0.6s backwards;
}

.infoCard {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 16px;
  padding: 2rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: flex;
  gap: 1.5rem;
  transition: all 0.3s ease;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
}

.infoCard:hover {
  transform: translateX(10px);
  background: rgba(255, 255, 255, 0.15);
}

.infoIcon {
  font-size: 3rem;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.2));
}

.infoContent h3 {
  color: white;
  font-size: 1.3rem;
  margin: 0 0 0.5rem 0;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);
}

.infoContent p {
  color: rgba(255, 255, 255, 0.9);
  margin: 0;
  line-height: 1.6;
}

/* ========================================
   FOOTER
   ======================================== */

.dashboardFooter {
  text-align: center;
  padding: 2rem;
  color: white;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(10px);
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  animation: fadeIn 0.6s ease-out 0.8s backwards;
}

.dashboardFooter p {
  margin: 0.5rem 0;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);
}

/* ========================================
   ANIMACIONES
   ======================================== */

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes float {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

/* ========================================
   RESPONSIVE
   ======================================== */

@media (max-width: 1200px) {
  .featuresGrid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .content {
    padding: 1.5rem;
  }

  .welcomeCard {
    padding: 2rem;
  }

  .welcomeHeader {
    flex-direction: column;
    gap: 1.5rem;
  }

  .welcomeTitle {
    font-size: 2rem;
  }

  .timeDisplay {
    text-align: left;
  }

  .time {
    font-size: 2rem;
  }

  .featuresGrid {
    grid-template-columns: 1fr;
  }

  .statsGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .infoCards {
    grid-template-columns: 1fr;
  }

  .infoCard {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .welcomeTitle {
    font-size: 1.75rem;
  }

  .statsGrid {
    grid-template-columns: 1fr;
  }

  .sectionTitle {
    font-size: 1.5rem;
  }
}

